// 反復ドリル（5パターン）生成スクリプト
// CLF-C02 の高頻出12テーマについて、5つの出題パターンを各7問前後で用意し、
// アプリ側で毎回ランダムに出題する（定着重視）。問題文にパターン名は表示しない。
//   P1 用途/場面→サービス・用語   P2 サービス/用語→説明（逆方向）
//   P3 シナリオ判断              P4 穴埋め（キーワード想起）
//   P5 区別・誤り探し
// すべて tag「ドリル」を付与。id は qd-<theme>-<n>。build_lessons.js が接頭辞でプール化する。
// 正解は元データで index 0 に置き、生成時にローテーションで①〜④へ均等分散する。
//   node design/build_drills.js
const fs = require("fs");
const path = require("path");
const ROOT = path.join(__dirname, "..");
const file = path.join(ROOT, "Resources/questions.json");
const existing = JSON.parse(fs.readFileSync(file, "utf8"));

// q(id, domain, service, difficulty, 質問, [正解,誤1,誤2,誤3], 解説, [誤1理由,誤2理由,誤3理由], tags, note)
const q = (id, domain, service, difficulty, question, choices, explanation, wrongs, tags, beginnerNote) => ({
  id, question, choices, correctAnswers: [0], explanation,
  wrongChoiceExplanations: { "1": wrongs[0], "2": wrongs[1], "3": wrongs[2] },
  domain, service, difficulty, tags: [...tags, "ドリル"], beginnerNote,
});

const NEW = [];
const T = (arr) => NEW.push(...arr);

