// __MORE_THEMES__

// ---- 正解位置をローテーションで①〜④へ均等分散 ----
function rotate(item, t) {
  if (t === 0) return item;
  const n = item.choices.length;
  const nc = new Array(n);
  for (let j = 0; j < n; j++) nc[(j + t) % n] = item.choices[j];
  const cor = item.correctAnswers.map((c) => (c + t) % n);
  const w = {};
  for (const [k, v] of Object.entries(item.wrongChoiceExplanations)) w[String((Number(k) + t) % n)] = v;
  return { ...item, choices: nc, correctAnswers: cor, wrongChoiceExplanations: w };
}
const rotated = NEW.map((item, i) => rotate(item, i % 4));

// ---- マージ（qd-* は常に上書き＝生成スクリプトを唯一の正とする）----
const byId = new Map(existing.map((x) => [x.id, x]));
let added = 0;
for (const item of rotated) { if (!byId.has(item.id)) added++; byId.set(item.id, item); }
// 旧5問版（qd-*-1〜5のうち今回定義しないもの）が残らないよう、qd- で今回未定義のIDは削除しない
// （ID体系は踏襲しているため上書きで最新化される）
const merged = Array.from(byId.values());
fs.writeFileSync(file, JSON.stringify(merged, null, 2) + "\n", "utf8");

const pos = [0, 0, 0, 0];
rotated.forEach((x) => pos[x.correctAnswers[0]]++);
const byTheme = {};
rotated.forEach((x) => { const t = x.id.replace(/-\d+$/, ""); byTheme[t] = (byTheme[t] || 0) + 1; });
console.log(`ドリル追加/更新: ${rotated.length}問（新規 ${added}）/ 合計 ${merged.length}`);
console.log("正解位置 ①②③④:", pos.join(" / "));
console.log("テーマ別問題数:", byTheme);
